mapper.select:
SELECT ty.id, ty.year, ty.dept_id, ty.dept_name, ty.create_user_name, ty.create_time, temp.* FROM ( SELECT metrics,shop_id,min(shop_name) AS shopName,main_id, COALESCE(SUM ( CASE WHEN month = 1 THEN value ELSE NULL END )*${multiplyNum},NULL) AS january, COALESCE(SUM ( CASE WHEN month = 2 THEN value ELSE NULL END )*${multiplyNum},NULL) AS february, COALESCE(SUM ( CASE WHEN month = 3 THEN value ELSE NULL END )*${multiplyNum},NULL) AS march, COALESCE(SUM ( CASE WHEN month = 4 THEN value ELSE NULL END )*${multiplyNum},NULL) AS april, COALESCE(SUM ( CASE WHEN month = 5 THEN value ELSE NULL END )*${multiplyNum},NULL) AS may, COALESCE(SUM ( CASE WHEN month = 6 THEN value ELSE NULL END )*${multiplyNum},NULL) AS june, COALESCE(SUM ( CASE WHEN month = 7 THEN value ELSE NULL END )*${multiplyNum},NULL) AS july, COALESCE(SUM ( CASE WHEN month = 8 THEN value ELSE NULL END )*${multiplyNum},NULL) AS august, COALESCE(SUM ( CASE WHEN month = 9 THEN value ELSE NULL END )*${multiplyNum},NULL) AS september, COALESCE(SUM ( CASE WHEN month = 10 THEN value ELSE NULL END )*${multiplyNum},NULL) AS october, COALESCE(SUM ( CASE WHEN month = 11 THEN value ELSE NULL END )*${multiplyNum},NULL) AS november, COALESCE(SUM ( CASE WHEN month = 12 THEN value ELSE NULL END )*${multiplyNum},NULL) AS december FROM bi_target_shop_setting WHERE metrics=#{params.metrics} AND is_deleted = FALSE GROUP BY metrics,shop_id,main_id ) temp LEFT JOIN bi_target_year ty ON temp.main_id = ty.id WHERE ty.is_deleted=false
AND ty.year =#{params.year}
AND ty.dept_id =#{params.deptId}
AND temp.shopName ILIKE concat('%', #{params.name}::text ,'%')
${params.permissionSql}
ORDER BY ty.id DESC

select btss.shop_name as typeName, btss.month, btss.value from bi_target_year bty left join bi_target_shop_setting btss on btss.is_deleted = false and bty.id = btss.main_id
bty.is_deleted = false
and btss.metrics = #{params.metrics}
and bty.year = to_char(#{params.startTime},'yyyy')::INTEGER and btss.month between 1 and 12
and bty.dept_id in
#{item}
and btss.shop_name in
#{item}

SELECT COALESCE(sum(january)*${multiplyNum},0) AS januaryTotal, COALESCE(sum(february)*${multiplyNum},0) AS februaryTotal, COALESCE(sum(march)*${multiplyNum},0) AS marchTotal, COALESCE(sum(april)*${multiplyNum},0) AS aprilTotal, COALESCE(sum(may)*${multiplyNum},0) AS mayTotal, COALESCE(sum(june)*${multiplyNum},0) AS juneTotal, COALESCE(sum(july)*${multiplyNum},0) AS julyTotal, COALESCE(sum(august)*${multiplyNum},0) AS augustTotal, COALESCE(sum(september)*${multiplyNum},0) AS septemberTotal, COALESCE(sum(october)*${multiplyNum},0) AS octoberTotal, COALESCE(sum(november)*${multiplyNum},0) AS novemberTotal, COALESCE(sum(december)*${multiplyNum},0) AS decemberTotal FROM ( SELECT metrics,main_id,min(shop_name) AS shopName, SUM ( CASE WHEN month = 1 THEN value ELSE 0 END ) AS january, SUM ( CASE WHEN month = 2 THEN value ELSE 0 END ) AS february, SUM ( CASE WHEN month = 3 THEN value ELSE 0 END ) AS march, SUM ( CASE WHEN month = 4 THEN value ELSE 0 END ) AS april, SUM ( CASE WHEN month = 5 THEN value ELSE 0 END ) AS may, SUM ( CASE WHEN month = 6 THEN value ELSE 0 END ) AS june, SUM ( CASE WHEN month = 7 THEN value ELSE 0 END ) AS july, SUM ( CASE WHEN month = 8 THEN value ELSE 0 END ) AS august, SUM ( CASE WHEN month = 9 THEN value ELSE 0 END ) AS september, SUM ( CASE WHEN month = 10 THEN value ELSE 0 END ) AS october, SUM ( CASE WHEN month = 11 THEN value ELSE 0 END ) AS november, SUM ( CASE WHEN month = 12 THEN value ELSE 0 END ) AS december FROM bi_target_shop_setting WHERE metrics=#{params.metrics} AND is_deleted = FALSE GROUP BY metrics,main_id ) temp LEFT JOIN bi_target_year ty ON temp.main_id = ty.id WHERE ty.is_deleted=false
AND ty.year =#{params.year}
AND ty.dept_id =#{params.deptId}
AND temp.shopName ILIKE concat('%', #{params.name}::text ,'%')
${params.permissionSql}
